<template><a-card title="操作审计"><a-space wrap style="margin-bottom:16px"><a-input v-model="filters.action" placeholder="动作，如 user.create"/><a-select v-model="filters.resource" placeholder="资源" allow-clear style="width:150px"><a-option>user</a-option><a-option>role</a-option><a-option>session</a-option><a-option>api</a-option><a-option>audit</a-option></a-select><a-select v-model="filters.outcome" placeholder="结果" allow-clear style="width:150px"><a-option>success</a-option><a-option>denied</a-option><a-option>failed</a-option></a-select>
<a-input v-model="filters.actor_id" placeholder="主体ID（正整数）"/><a-input v-model="filters.start" placeholder="开始，如 2026-11-20T00:00:00+08:00" style="width:min(330px,100%)"/><a-input v-model="filters.end" placeholder="结束，带时区ISO时间" style="width:min(330px,100%)"/>
<a-button @click="search">查询</a-button><a-button @click="exportCsv" :loading="exporting">导出安全CSV</a-button></a-space><p>导出使用当前筛选，最多5000行，超限拒绝而不截断。仅安全审计字段，不含密码、密钥、邮箱、IP 或原始请求。</p>
<a-alert v-if="error" type="error">{{error}} <a-button @click="load">重试</a-button></a-alert><a-alert v-if="exportError" type="error">{{exportError}} <a-button @click="exportCsv">重试导出</a-button></a-alert>
<a-table :data="rows" :columns="columns" :loading="loading" :pagination="pagination" @page-change="changePage" row-key="id" :scroll="{x:850}"/></a-card></template>
<script setup lang="ts">
import {ref,reactive,onMounted} from 'vue'
import client from '@/api/client'
const rows=ref<any[]>([]),error=ref(''),loading=ref(false),filters=reactive({action:'',resource:'',outcome:'',actor_id:'',start:'',end:''}),pagination=reactive({current:1,pageSize:20,total:0,showTotal:true}),exporting=ref(false),exportError=ref('')
let generation=0
const columns=[{title:'时间',dataIndex:'created_at',width:220},{title:'主体',dataIndex:'actor_name',width:140},{title:'动作',dataIndex:'action',width:180},{title:'资源',dataIndex:'resource'},{title:'对象ID',dataIndex:'object_id'},{title:'结果',dataIndex:'outcome'}]
async function load(){const id=++generation;loading.value=true;error.value='';try{const r:any=await client.get('/audit/logs/',{params:{...filters,page:pagination.current,page_size:pagination.pageSize}});if(id!==generation)return;rows.value=r.data;pagination.current=r.pagination.page;pagination.total=r.pagination.total}catch(e:any){if(id===generation)error.value=e.message}finally{if(id===generation)loading.value=false}}
async function exportCsv(){if(exporting.value)return;exporting.value=true;exportError.value='';try{const params=new URLSearchParams();Object.entries(filters).forEach(([k,v])=>{if(v)params.set(k,v)});const response=await fetch('/api/audit/export/?'+params.toString(),{credentials:'same-origin',cache:'no-store'});if(!response.ok){const body=await response.json();throw new Error(body.error?.message||'导出失败，请重试')}const blob=await response.blob();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='operation-audit.csv';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e:any){exportError.value=e.message||'导出失败，请重试'}finally{exporting.value=false}}
function search(){pagination.current=1;load()}function changePage(p:number){pagination.current=p;load()}onMounted(load)
</script>
